interface Updatable { update(dt: number): void }     // the hook

const entities: Updatable[] = [new Guard()];         // the collection
let prev = 0;
function frame(now: number): void {
  const dt = Math.min((now - prev) / 1000, 0.25);    // ms -> s, clamped
  prev = now;
  for (const e of entities) e.update(dt);            // typed driver walk
  requestAnimationFrame(frame);                      // one-shot: re-request
}
requestAnimationFrame(frame);
